async () => {
  const rows=[]; const counts=[];
  for (let p=1;p<=10;p++){
    const html=await (await fetch('?page='+p)).text();
    const d=new DOMParser().parseFromString(html,'text/html');
    const trs=[...d.querySelectorAll('table tbody tr, table tr')].filter(tr=>tr.querySelectorAll('td').length);
    counts.push(trs.length);
    for(const tr of trs){const c=[...tr.querySelectorAll('td')].map(t=>t.textContent.trim()); rows.push(c);}
  }
  const ids=new Set(rows.map(r=>r[0]));
  const customers=[...new Set(rows.map(r=>r[1]))]; const statuses=[...new Set(rows.map(r=>r[3]))];
  const m=rows.filter(r=>r[1]==='Northwind'&&r[3]==='overdue');
  const cents=m.reduce((s,r)=>s+Math.round(parseFloat(r[2].replace(/[$,]/g,''))*100),0);
  return {counts,total:rows.length,unique:ids.size,customers,statuses,m,sum:cents/100};
}
